class Solution {
    std::unordered_map<std::string, std::string> parent;
    std::string find(const std::string& x) {
        if (!parent.count(x)) parent[x] = x;
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(const std::string& x, const std::string& y) {
        std::string rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }
    void backtrack(int idx, const std::vector<std::string>& words, std::vector<std::string>& path,
                   std::unordered_map<std::string, std::vector<std::string>>& groups, std::vector<std::string>& res) {
        if (idx == words.size()) {
            std::string s = path[0];
            for (int i = 1; i < path.size(); ++i) s += " " + path[i];
            res.push_back(s);
            return;
        }
        std::string w = words[idx];
        std::string root = find(w);
        std::vector<std::string> candidates = groups.count(root) ? groups[root] : std::vector<std::string>{w};
        for (const auto& cand : candidates) {
            path.push_back(cand);
            backtrack(idx + 1, words, path, groups, res);
            path.pop_back();
        }
    }
