    std::vector<std::string> generateSentences(std::vector<std::vector<std::string>>& synonyms, std::string text) {
        for (const auto& syn : synonyms) unite(syn[0], syn[1]);

        std::unordered_map<std::string, std::set<std::string>> groupSets;
        for (const auto& [w, p] : parent) groupSets[find(w)].insert(w);

        std::unordered_map<std::string, std::vector<std::string>> groups;
