class Solution {
    java.util.Map<String, String> parent = new java.util.HashMap<>();
    String find(String x) {
        parent.putIfAbsent(x, x);
        if (!parent.get(x).equals(x)) parent.put(x, find(parent.get(x)));
        return parent.get(x);
    }
    void union(String x, String y) {
        String rx = find(x), ry = find(y);
        if (!rx.equals(ry)) parent.put(rx, ry);
    }
    void backtrack(int idx, String[] words, java.util.List<String> path,
                   java.util.Map<String, java.util.List<String>> groups, java.util.List<String> res) {
        if (idx == words.length) {
            res.add(String.join(" ", path));
            return;
        }
        String w = words[idx];
        String root = find(w);
        java.util.List<String> candidates = groups.getOrDefault(root, java.util.List.of(w));
        for (String cand : candidates) {
            path.add(cand);
            backtrack(idx + 1, words, path, groups, res);
            path.remove(path.size() - 1);
        }
    }
    public java.util.List<String> generateSentences(java.util.List<java.util.List<String>> synonyms, String text) {
        for (java.util.List<String> syn : synonyms) union(syn.get(0), syn.get(1));

        java.util.Map<String, java.util.TreeSet<String>> groupSets = new java.util.HashMap<>();
        for (String w : parent.keySet()) {
            groupSets.computeIfAbsent(find(w), k -> new java.util.TreeSet<>()).add(w);
        }

        java.util.Map<String, java.util.List<String>> groups = new java.util.HashMap<>();
        for (java.util.Map.Entry<String, java.util.TreeSet<String>> entry : groupSets.entrySet()) {
            groups.put(entry.getKey(), new java.util.ArrayList<>(entry.getValue()));
        }

        String[] words = text.split(" ");
        java.util.List<String> res = new java.util.ArrayList<>();
        backtrack(0, words, new java.util.ArrayList<>(), groups, res);
        return res;
    }
}

var generateSentences = function(synonyms, text) {
    const parent = new Map();
    const find = (x) => {
        if (!parent.has(x)) parent.set(x, x);
        if (parent.get(x) !== x) parent.set(x, find(parent.get(x)));
        return parent.get(x);
    };
    const union = (x, y) => {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent.set(rx, ry);
    };

    for (const [u, v] of synonyms) union(u, v);

    const groups = new Map();
    for (const w of parent.keys()) {
        const root = find(w);
        if (!groups.has(root)) groups.set(root, []);
        groups.get(root).push(w);
    }
    for (const [root, list] of groups.entries()) {
        list.sort();
    }

    const words = text.split(' ');
    const res = [];
    const backtrack = (idx, path) => {
        if (idx === words.length) {
            res.push(path.join(' '));
            return;
        }
        const w = words[idx];
        const root = find(w);
        const candidates = groups.has(root) ? groups.get(root) : [w];
        for (const cand of candidates) {
            path.push(cand);
            backtrack(idx + 1, path);
            path.pop();
        }
    };
    backtrack(0, []);
    return res;
};
